import {COUNTRIES,internationalPhone} from './countries.mjs';
const eye='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="eye-slash" d="M3 3l18 18"/></svg>';
export function passwordField(name,label,extra=''){return '<label class="field" for="'+name+'"><span>'+label+'</span><span class="password-control"><input id="'+name+'" name="'+name+'" aria-label="'+label+'" type="password" '+extra+'><button type="button" class="password-eye" data-password-toggle="'+name+'" aria-label="Show '+label.toLowerCase()+'" aria-pressed="false">'+eye+'</button></span></label>';}
export function bindPasswordVisibility(root){root.querySelectorAll('[data-password-toggle]').forEach(button=>button.onclick=()=>{const input=root.querySelector('#'+button.dataset.passwordToggle),show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',(show?'Hide ':'Show ')+(button.dataset.passwordToggle==='confirmPassword'?'confirm password':'password'));});}
export function countryPhoneField(){return '<div class="phone-group"><label class="field" for="phoneCountry"><span>Country / calling code</span><select id="phoneCountry" name="phoneCountry" autocomplete="country"><option value="">Choose a country</option>'+COUNTRIES.map(c=>'<option value="'+c.code+'">'+c.name+' ('+c.code+')'+(c.dial?' +'+c.dial:' · No assigned dial code')+'</option>').join('')+'</select></label><label class="field" for="phone"><span>Phone number (optional)</span><input id="phone" name="phone" type="tel" maxlength="24" autocomplete="tel-national" placeholder="National number"></label></div>';}
export function normalizeSignupPhone(values){return {...values,phone:internationalPhone(values.phoneCountry,values.phone)};}
